#include <unordered_map>
#include <string>

using namespace std;

class Solution {
    unordered_map<string, string> longToShort, shortToLong;
    string domain = "http://tinyurl.com/";
    int id = 0;

public:
    string encode(string longUrl) {
        if (longToShort.count(longUrl)) return domain + longToShort[longUrl];
        string code = to_string(id++);
        longToShort[longUrl] = code;
        shortToLong[code] = longUrl;
        return domain + code;
    }

    string decode(string shortUrl) {
        string code = shortUrl.substr(domain.size());
        return shortToLong[code];
    }
};
